import React from "react";
import { useCurrentFrame, useVideoConfig, AbsoluteFill, interpolate, spring } from '../remotionShim';
{/* Start Google Fonts Loader */ }
const useFontLoader = (fonts: string[]) => {
  const stableFonts = React.useMemo(() => {
    const unique = [...new Set(fonts.map(f => f.trim()))].sort();
    return unique;
  }, [fonts.join("|")]);

  React.useEffect(() => {
    const unloaded = stableFonts.filter(
      (font) =>
        !document.querySelector(
          `link[href*="${font.replace(/\s+/g, "+")}"]`
        )
    );

    if (unloaded.length === 0) return;

    const url = `https://fonts.googleapis.com/css2?${unloaded
      .map((font) => `family=${font.replace(/\s+/g, "+")}:wght@400;600;700`)
      .join("&")}&display=swap`;

    const link = document.createElement("link");
    link.rel = "stylesheet";
    link.href = url;

    document.head.appendChild(link);
  }, [stableFonts]);
};
{/* End Google Fonts Loader */ }



export type LaughingManProps = Record<string, any>;

const LaughingMan: React.FC<LaughingManProps> = ({
  backgroundColor = "#87CEEB",
  transparentBackground = false,
  skinColor = "#fce5cd",
  lipColor = "#d94c50",
  eyeColor = "#333333",
  laughSpeed = 8,
  durationInSeconds = 10,
}) => {
  useFontLoader(["Fredoka One"]);

  const frame = useCurrentFrame();
  const { width, height } = useVideoConfig();

  // --- Safe Color Logic ---
  const finalBgColor = transparentBackground ? "transparent" : backgroundColor;

  // --- Dimensions & Positioning ---
  const faceSize = Math.min(width, height) * 0.5;
  const centerX = width / 2;
  const centerY = height / 2;

  // --- Animation Drivers ---
  
  // 1. Head Bob (Slower, rocking motion)
  // Input: Sine wave [-1, 1], Output: Rotation degrees [-5, 5]
  const headBobSine = Math.sin(frame / 10);
  const headRotation = interpolate(headBobSine, [-1, 1], [-5, 5]);
  
  // 2. Laugh Cycle (Fast, opening/closing mouth)
  // We use a sine wave based on laughSpeed.
  // We map sine output [-1, 1] to "openness" factor [0, 1]
  const laughSine = Math.sin(frame * (laughSpeed / 10)); 
  const mouthOpenFactor = interpolate(laughSine, [-1, 1], [0, 1]);

  // 3. Eye Squint (Reacts to laughter intensity)
  // When mouth is most open, eyes squint more (scaleY decreases)
  const eyeScaleY = interpolate(mouthOpenFactor, [0, 1], [1, 0.4]);

  // --- Lip Path Construction ---
  // Dynamic paths based on mouthOpenFactor
  const lipWidth = faceSize * 0.6;
  const lipHeightBase = faceSize * 0.15;
  const maxOpen = faceSize * 0.15; // How far the jaw drops

  // Offsets for animation
  const topLipY = - (mouthOpenFactor * (maxOpen * 0.3)); // Moves up slightly
  const bottomLipY = (mouthOpenFactor * maxOpen);        // Moves down significantly

  return (
    <AbsoluteFill style={{ backgroundColor: finalBgColor, fontFamily: "Fredoka One" }}>
      
      {/* --- HA HA TEXT BUBBLES --- */}
      {/* We create 3 bubbles with staggered phases */}
      {[0, 1, 2].map((i) => {
        const offset = i * 20;
        const loopDuration = 45; // frames
        const localFrame = (frame + offset) % loopDuration;
        
        // Animate opacity and float up
        const opacity = interpolate(localFrame, [0, 10, 35, 45], [0, 1, 1, 0], { extrapolateRight: "clamp" });
        const floatY = interpolate(localFrame, [0, 45], [0, -100]);
        const scale = interpolate(localFrame, [0, 10], [0.5, 1.2], { extrapolateRight: "clamp" });

        // Position around the head
        const side = i % 2 === 0 ? 1 : -1;
        const posX = centerX + (faceSize * 0.6 * side) + (i * 20);
        const posY = centerY - (faceSize * 0.4) - (i * 10);

        return (
          <div
            key={i}
            style={{
              position: "absolute",
              left: posX,
              top: posY,
              opacity,
              transform: `translateY(${floatY}px) scale(${scale}) rotate(${side * 15}deg)`,
              color: "white",
              fontSize: faceSize * 0.25,
              fontWeight: "bold",
              textShadow: "3px 3px 0px rgba(0,0,0,0.2)",
              pointerEvents: "none",
              zIndex: 0 // Behind face if overlapping, or adjust zIndex
            }}
          >
            HA
          </div>
        );
      })}

      {/* --- HEAD CONTAINER --- */}
      <div
        style={{
          position: "absolute",
          width: faceSize,
          height: faceSize,
          left: centerX - faceSize / 2,
          top: centerY - faceSize / 2,
          transform: `rotate(${headRotation}deg)`,
          transformOrigin: "center bottom",
        }}
      >
        {/* Face Shape */}
        <div
          style={{
            width: "100%",
            height: "100%",
            borderRadius: "50%",
            backgroundColor: skinColor,
            boxShadow: "0 10px 20px rgba(0,0,0,0.1)",
            position: "absolute",
          }}
        />

        {/* Eyes Group */}
        <div style={{ position: "absolute", top: "35%", width: "100%", height: "20%" }}>
          {/* Left Eye */}
          <div
            style={{
              position: "absolute",
              left: "25%",
              width: "15%",
              height: "15%",
              backgroundColor: eyeColor,
              borderRadius: "50%",
              transform: `scaleY(${eyeScaleY})`,
            }}
          />
           {/* Right Eye */}
           <div
            style={{
              position: "absolute",
              right: "25%",
              width: "15%",
              height: "15%",
              backgroundColor: eyeColor,
              borderRadius: "50%",
              transform: `scaleY(${eyeScaleY})`,
            }}
          />
        </div>

        {/* Mouth Container */}
        <div
          style={{
            position: "absolute",
            top: "60%",
            left: "50%",
            transform: "translateX(-50%)",
            width: lipWidth,
            height: lipHeightBase * 3, // Container space for opening
            display: "flex",
            flexDirection: "column",
            alignItems: "center",
            justifyContent: "center",
          }}
        >
          {/* MOUTH INTERIOR (Visible when lips separate) */}
          <div
            style={{
              position: "absolute",
              width: lipWidth * 0.8,
              height: (bottomLipY - topLipY) + 20, // Dynamic height based on separation
              backgroundColor: "#4a0e0e", // Dark red inside mouth
              top: lipHeightBase + topLipY + 5,
              borderRadius: "20px",
              overflow: "hidden"
            }}
          >
            {/* Tongue */}
            <div
              style={{
                position: "absolute",
                bottom: -10,
                left: "50%",
                transform: "translateX(-50%)",
                width: "60%",
                height: "50%",
                backgroundColor: "#e06c75",
                borderRadius: "50% 50% 0 0",
              }}
            />
          </div>

          {/* UPPER LIP */}
          <svg
            width={lipWidth}
            height={lipHeightBase}
            style={{
              position: "absolute",
              top: lipHeightBase / 2, // Centered initially
              transform: `translateY(${topLipY}px)`,
              zIndex: 10,
              overflow: "visible"
            }}
            viewBox={`0 0 100 50`}
          >
            {/* Cupid's bow shape */}
            <path
              d="M 0 50 Q 25 0 50 20 Q 75 0 100 50 Q 50 30 0 50 Z"
              fill={lipColor}
              stroke={lipColor} // Make it thick
              strokeWidth="2"
              strokeLinejoin="round"
            />
          </svg>

          {/* LOWER LIP */}
          <svg
            width={lipWidth}
            height={lipHeightBase}
            style={{
              position: "absolute",
              top: lipHeightBase / 2 + 2, // Slightly below upper lip initially
              transform: `translateY(${bottomLipY}px)`,
              zIndex: 10,
              overflow: "visible"
            }}
            viewBox={`0 0 100 50`}
          >
            {/* Rounded bottom lip */}
            <path
              d="M 0 0 Q 50 60 100 0 Q 50 20 0 0 Z"
              fill={lipColor}
              stroke={lipColor}
              strokeWidth="2"
              strokeLinejoin="round"
            />
          </svg>

        </div>
      </div>
    </AbsoluteFill>
  );
};

export default LaughingMan;